INSERT INTO nb_card_knowledge (card_id,audience_code,language_code,content_version,theme,keywords_json,meaning_text,symbolism_text,other_direction_text,status_code,provenance_code) VALUES
('major-00','ADULT','de','0.1.0','EIN SPRUNG INS UNBEKANNTE','["DER SUCHENDE", "ERGRÜNDUNG", "INNERES KIND", "ERWACHEN", "UNSCHULD"]','Wenn der Narr in einer Tarot-Lesung erscheint, kann er eine naive Person bedeuten, die dennoch Weisheit vermitteln kann und Einfachheit und besondere Einsicht verkörpert. Er weist auch auf das innere Kind hin, die Dimension Ihres Selbst, das sich unverzagt, furchtlos und ohne Negativität kopfüber in neue Erfahrungen stürzt. Der Narr kann den Beginn eines stimulierenden Unternehmens oder einer neuen spirituellen Reise verkörpern. Die Karte sagt Ihnen, auf Ihr Herz zu hören und Ihren Träumen zu folgen. Es ist allerdings keine ganz positive Karte. Wenn Sie sich in unbekannte Gebiete aufmachen, können Sie sich nicht sicher sein, was Sie entdecken. Es besteht die Gefahr, dass Sie einen Fehler machen und Ihre Taten bereuen - aber Risiko ist das, was uns leben und nicht einfach nur existieren lässt.',NULL,'— BEDEUTUNG DER UMGEKEHRTEN KARTE： Optimismus ist eine Sache, Rücksichtslosigkeit eine andere. Der umgekehrte Narr weist auf eine verantwortungslose Haltung und auf mangelnde Fürsorge hin - mit destruktiven Folgen. Überdenken Sie das','draft-review','source-derived-draft'),
('major-00','CHILD','de','0.1.0','EIN SPRUNG INS UNBEKANNTE','["DER SUCHENDE", "ERGRÜNDUNG", "INNERES KIND", "ERWACHEN", "UNSCHULD"]','Diese Karte erzählt von ein sprung ins unbekannte. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-01','ADULT','de','0.1.0','SICH DIE UMSTÄNDE ZUNUTZE MACHEN','["SELBSTVERTRAUEN", "BEFÄHIGUNG", "FÜHRER", "VERÄNDERUNG BEWIRKEN", "TALENT"]','Das Erscheinen des Magiers signalisiert Selbstvertrauen und Herrschaft - die Macht, Dinge geschehen zu lassen. Diese Karte erinnert uns daran, dass wir Herr unseres eigenen Lebens sind und die Fähigkeit besitzen, das zu bekommen, was wir wollen. Wenn der Magier bei einer TarotLesung auftaucht, bereit seit Ihr Selbstvertrauen zu lenken, damit Sie Großes erreichen können. Der Magier ist eine der mächtigsten Figuren im Tarot. Vielleicht ist in Ihrem Leben eine machtvolle Figur aufgetaucht, die Ihnen hilft, die Dinge zum Besseren zu verändern. Oder es steht eine wichtige Entwicklung in beruflicher, spiritueller oder gesundheitlicher Hinsicht an. Dies ist die Zeit, in die Welt hinauszugehen und herauszufinden, was Sie wollen, sei es ein neuer Partner oder ein Berufswechsel.',NULL,'*S・BEDEUTUNG DER UMGEKEHRTEN KARTE Macht kann fehlgeleitet werden; bevor Sie Veranderungen bewirken oder Erelgnisse manipulieren wollen. Uber Ihre Beweggrinde nachdenken. Der Zweck heiligt nicht immer die Mittel. Vorsicht vor einer charmanten, aber nicht vertrauenswirdigen Person. 215 III 53 @① 133237 LI LAAN - 0','draft-review','source-derived-draft'),
('major-01','CHILD','de','0.1.0','SICH DIE UMSTÄNDE ZUNUTZE MACHEN','["SELBSTVERTRAUEN", "BEFÄHIGUNG", "FÜHRER", "VERÄNDERUNG BEWIRKEN", "TALENT"]','Diese Karte erzählt von sich die umstände zunutze machen. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-02','ADULT','de','0.1.0','Die Hohepriesterin','[]','INSPIRATION, INTUITION UND GEHEIMNISSE WEITBLICK WAHRNEHMUNG ENTDECKUNG INNERE STIMME SCHWEIGEN DIE KAISERIN FÜLLE IM PHYSISCHEN BEREICH GROSSZÜGIGKEIT PFLEGEN WOHLERGEHEN SICHERHEIT KOMFORT Die Hohepriesterin ist eine würdevolle Figur voller Gelehrsamkeit und Weisheit, jemand, der intuitiv und fähig ist, verborgene Wahrheiten zu erahnen und die subtile Macht des Weiblichen zu verkörpern. Taucht diese Karte in einem Spread auf, so kann sie eine übersinnliche Offenbarung darstellen, die von einem Traum, dem Gefühl von einer höheren Macht in Ihrem Leben oder intensiver Arbeit an Ihrem spirituellen Selbst herrührt. Es ist möglich, dass Ihr Leben in Kürze von einem neuen Verständnis erhellt wird. Diese Karte besitzt eine ruhige Energie und deutet an, dass eine Periode des Rückzugs von der Welt erforderlich ist, damit Sie Ihre innere Stimme finden. Die Hohepriesterin ist eher eine passive als eine dynamische Kraft und besagt, dass es manchmal besser ist, zu beobachten und auf die innere Stimme zu warten, statt zu reagieren und die Dinge zu steuern. • BEDEUTUNG DER UMGEKEHRTEN KARIE: Hören Sie nicht auf Ihre Intuition. Zu viel Unabhängigkeit und längere Isolation können zu Egoismus führen und den Umgang mit anderen erschweren. Die Kaiserin widmet sich irdischen Angelegenheiten und sinnlichen Freuden. Diese Karte verkörpert Fülle, Fruchtbarkeit und Fürsorge für andere. Die Kaiserin erinnert Sie daran, dass Sie ein physisches Wesen mit materiellen Bedürfnissen sind. Das Auftauchen dieser Karte deutet darauf hin, dass Sie mit materiellen Segnungen überschüttet werden und sich wohl und zufrieden fühlen - die Kaiserin ist die praktische, fürsorgliche Mutter Erde, die Leben schenkt und für Nahrung sorgt. Geschäftliche Unternehmungen können zu Wohlstand fuhren, und bisherige Anstrengungen werden belohnt: Wir ernten, was wir gesät haben. Kreatives Potenzial wird gefördert, und bei schlechter Gesundheit verleiht die Kaiserin neue Kraft - was immer man benötigt, wird zur Verfügung gestellt. Als Mutterfigur blickt die Kaiserin liebevoll auf das Familienleben.',NULL,'Mütter konzentrieren sich oft zu sehr auf die Bedürfnisse anderer; eventuell verhält sich jemand einem Partner oder Familienmitglied gegenüber auf geistestötende Weise. Vernachlässigen Sie Ihre eigenen Bedürfnisse? Sind Fruchtbarkeit oder mangelnde kreative Möglichkeiten ein Problem? 嵌','draft-review','source-derived-draft'),
('major-02','CHILD','de','0.1.0','Die Hohepriesterin','[]','Diese Karte erzählt von die hohepriesterin. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-03','ADULT','de','0.1.0','Wachsen, nähren und entstehen lassen','["Fülle", "Fürsorge", "Kreativität"]','Die Herrscherin verbindet Schöpfung, Fürsorge und Wachstum. Sie kann auf Bedingungen hinweisen, unter denen etwas Lebendiges, Kreatives oder Beziehungshaftes gedeihen kann.',NULL,'Die andere Blickrichtung macht sichtbar, wenn Fürsorge in Selbstvernachlässigung, Überversorgung oder festhaltende Kontrolle kippt.','draft-review','neuroways-fallback'),
('major-03','CHILD','de','0.1.0','Wachsen, nähren und entstehen lassen','["Fülle", "Fürsorge", "Kreativität"]','Diese Karte erzählt von wachsen, nähren und entstehen lassen. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-04','ADULT','de','0.1.0','KOPF ÜBER HERZ','["STÄRKE", "DEN EIGENEN WILLEN DURCHSETZEN", "DIE WELT FORMEN", "AUTORITÄT", "BESTIMMTHEIT"]','Der Kaiser bezeichnet einen Anführer, Ver-I sorger oder Vorgesetzten. Wenn diese Karte 1 auftaucht, ist möglicherweise eine männliche Präsenz in Ihrem Leben erschienen, ( 1 vielleicht als Mentor oder Vaterfigur oder als potenzieller Partner. Es kann auch sein, dass Sie Zugang zu dieser Dimension Ihrer selbst benötigen und methodisch an die Angelegenheit herangehen müssen. Ob Sie einen neuen Job anstreben oder sich mit Schwierigkeiten in einer Beziehung auseinandersetzen müssen, diese Karte rät, dass ein strukturierter, schrittweise ausgeführter Plan zu besseren Ergebnissen führt als eine emotionale, sporadische Reaktion. Selbst spiritueller Fortschritt muss die Selbstdisziplin und regelmäßige Praktik umfassen, die der Kaiser verkörpert.',NULL,'Der umgekehrte Kaiser kann auf eine erdrückende oder dominierende Person, eine Überbetonung von Macht oder Engstirnigkeit in Ihrem Denken hinweisen. Den Geist für die Ideen anderer öffnen. AP','draft-review','source-derived-draft'),
('major-04','CHILD','de','0.1.0','KOPF ÜBER HERZ','["STÄRKE", "DEN EIGENEN WILLEN DURCHSETZEN", "DIE WELT FORMEN", "AUTORITÄT", "BESTIMMTHEIT"]','Diese Karte erzählt von kopf über herz. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-05','ADULT','de','0.1.0','PHILOSOPH UND SEELENFUHRER','["INSTITUTION", "TRADITION", "RESPEKT", "MORALISCHE HALTUNG", "RELIGIÖSE STUDIEN"]','Der Hierophant oder Hohepriester ist Philosoph und spiritueller Führer. Diese Karte deutet darauf hin, dass der Fragende nach Antworten auf den Sinn des Lebens sucht. Im Gegensatz zur Hohepriesterin-Karte, die nahelegt, im Inneren nach den Antworten zu suchen, repräsentiert der Hierophant einen Pfad, dem andere vor Ihnen gefolgt sind, etwa eine etablierte Religion oder ein anderes Glaubenssystem, das vor allem Gruppenarbeit beinhaltet. Diese Karte kann einen vertrauenswürdigen Lehrer, Priester oder einen Therapeuten darstellen, der Sie einen bestimmten Weg der Entdeckung entlang führt. Denken Sie daran, zu hinterfragen, was Ihnen gesagt wird, statt unbedacht in die Fußstapfen einer anderen Person zu treten; vermeiden Sie, sich anzupassen, um anderen zu gefallen. Der Hierophant kann auch darauf hinweisen, sich auf die Bedürfnisse der Gruppe statt auf die eines Einzelnen zu konzentrieren.',NULL,'Jemand, den man verehrt oder dem man gehorcht, kann unter Umständen ein Heuchler sein, der falsche Wahrheiten verbreitet oder vorgibt, mehr zu wissen als andere. Vielleicht ignorieren Sie die Wahrheit aus Respekt für eine Führungsperson? 31','draft-review','source-derived-draft'),
('major-05','CHILD','de','0.1.0','PHILOSOPH UND SEELENFUHRER','["INSTITUTION", "TRADITION", "RESPEKT", "MORALISCHE HALTUNG", "RELIGIÖSE STUDIEN"]','Diese Karte erzählt von philosoph und seelenfuhrer. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-06','ADULT','de','0.1.0','ROMANZE UND LEBENSFÜHRUNG','["ANZIEHUNGSKRAFT", "HARMONIE", "SYNERGIE", "ZWEI OPTIONEN", "HINGABE"]','Diese Karte hat nicht unbedingt etwas mit Romanze zu tun. Manchmal weist sie darauf hin, dass man sich zwischen zwei Möglichkeiten entscheiden muss, vielleicht zwei Zielen, die verschiedene Teile Ihrer selbst ansprechen: Ihre spirituelle und weltliche oder Ihre emotionale und intellektuelle Seite. Die Liebenden können anzeigen, dass Sie Ihren Seelengefahrten gefunden haben und dass die Beziehung von Dauer sein wird. Feste Beziehungen aber erfordern Verzicht: Wenn Sie Ihre Wahl treffen, müssen Sie anderen Mäglichkeiten den Rücken kehren. Diese Karte zeigt an, dass die Wahl, die Sie treffen müssen, wichtig ist, garantiert aber, dass das Glück auf Sie wartet, wenn Sie mit Weisheit und Intuition wählen. Die Liebenden weisen auch auf Erfolg in einer Situation hin, in der zwei Menschen oder Gruppen geschäftlich, freundschaftlich oder romantisch zusammenkommen. ・・BEDEUTUNG DER UMGEKEHRTENKARTE Unentschlossenheit oder Schwankungen können dazu führen, dass man Chancen verpasst. Innerhalb einer Beziehung liegt ein Konflikt vor, moglicherweise in Form einer anderen Person. Es kann zu einer Scheidung oder Trennung kommen.',NULL,NULL,'draft-review','source-derived-draft'),
('major-06','CHILD','de','0.1.0','ROMANZE UND LEBENSFÜHRUNG','["ANZIEHUNGSKRAFT", "HARMONIE", "SYNERGIE", "ZWEI OPTIONEN", "HINGABE"]','Diese Karte erzählt von romanze und lebensführung. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-07','ADULT','de','0.1.0','EIN HART ERKÄMPFTER SIEG','["SIEGEN", "WEITERENTWICKLUNG", "TRIUMPH", "VERTRAUEN", "TATENDRANG"]','Der Wagen feiert Ihre Stärke und Entschlossenheit, Ihren Willen durchzusetzen. Er steht für Selbstvertrauen, Willenskraft und den Glauben an sich selbst. Taucht diese Karte in einer Tarot-Lesung auf, so haben Sie den Gegner geschlagen und sind triumphierend aus dem Gefecht hervorgegangen. Ihr Sieg kann klein oder groß sein - vielleicht haben Sie ein von Ihren Kollegen hart umkämpfte Beförderung ergattert oder es endlich geschafft, nach mehreren gescheiterten Versuchen das Rauchen aufzugeben. Worum es auch ging. Sie haben gesiegt und sich durchgesetzt, und diese Karte ermuntert Sie dazu, das Gefühl von Stolz und Befriedigung, das sich anschließend einstellt, zu genießen. In einer zukünftigen Position legt der Wagen nahe, dass sich der Erfolg einstellen wird — Sie haben die richtige Haltung.',NULL,'Der Wagen steht für Charakterstärke, deutet umgekehrt aber darauf hin, dass Sie arrogant und den Gefühlen anderer gegenüber rücksichtslos sind. Schadenfreude und rachsüchtige Aggression sind eines wahren Siegers unwürdig. 〜 今','draft-review','source-derived-draft'),
('major-07','CHILD','de','0.1.0','EIN HART ERKÄMPFTER SIEG','["SIEGEN", "WEITERENTWICKLUNG", "TRIUMPH", "VERTRAUEN", "TATENDRANG"]','Diese Karte erzählt von ein hart erkämpfter sieg. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-08','ADULT','de','0.1.0','DER MUT, HINDERNISSE','["ZU ,BERWINDEN", "INNERE KRAFT", "GEISTIGE AUSGEGLICHENHEIT", "WAHRNEHMEN VON FÄHIGKEITEN", "WILLENSSTÄRKE"]','Wir alle werden in unserem Leben mit Schwierigkeiten konfrontiert, und der härteste Kampf findet für gewöhnlich mit uns selbst statt. Die Stärke ist ein Aufruf, den notwendigen Mut aufzubringen, um Wut, Furcht und Zweifel in die richtigen Bahnen zu lenken, und die Bestätigung zu bekommen, dass Sie den Charakter zum Siegen haben. Die Stärke ist eine der Glückskarten in der Großen Arkana. Sie erscheint oft an einem entscheidenden Punkt in Ihrem Leben und zu einer Zeit, wenn getroffene Entscheidungen weitreichende, positive Folgen haben können. Die Karte zeigt an, dass Sie Weisheit und Selbstverständnis entwickelt haben und nicht mehr dem Ego mit seinen hemmungslosen Trieben ausgesetzt sind. Sie haben die notwendige Selbstkontrolle, Ihre Kraft zu nutzen und Ihr Potenzial zu verwirklichen.',NULL,'・・ BEDEUTUNG DER UMGEKEHRTEN KARTE: Kontrollveilust: Ver lierenthre negativen Triebe die Oberhand? Ein Hinweis auf Sucht oder ein schädliches Persönlichkeitsmerkm^ kommt zu einem Verlust der Willenskraft und es feht der Glaube, sich durchsetzen zu können. Sie brauchen Hille von äuβeren Quellen.','draft-review','source-derived-draft'),
('major-08','CHILD','de','0.1.0','DER MUT, HINDERNISSE','["ZU ,BERWINDEN", "INNERE KRAFT", "GEISTIGE AUSGEGLICHENHEIT", "WAHRNEHMEN VON FÄHIGKEITEN", "WILLENSSTÄRKE"]','Diese Karte erzählt von der mut, hindernisse. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-09','ADULT','de','0.1.0','SICH ZEIT ZUM NACHDENKEN NEHMEN','["AUFGEKLÄRTHEIT", "EINSAMKEIT", "BESINNUNG", "MEDITATION", "SELBSTVERWIRKLICHUNG"]','Jede spirituelle Reise erfordert Rückzug vom Druck und den Versuchungen der materiellen Welt, damit sich der Geist auf die innere Reise konzentriert. Der Eremit verkörpert das Gefühl des Zurückziehens und der Selbstgenügsamkeit. Der Eremit ist ein Urbild der Mythen und Geschichten aller Zivilisationen, und die Zeit ist eine dieser allegorischen Figuren. Diese Tarotkarte übermittelt die klare Botschaft, langsamer zu treten； Nachdenken ist erforderlich. Meditation oder Gebet können sich als wertvolles Hilfsmittel zum Bestimmen Ihrer Richtung erweisen, aber es ist auch sinnvoll, gesellschaftliche und berufliche Verpflichtungen zu reduzieren, um Zeit für sich selbst zu haben. Jetzt nicht in die Fußstapfen eines anderen treten, sondern bedacht, langsam und in Ruhe einen neuen Weg beschreiten und mit jedem Schritt Ihr Selbstbewusstsein stärken.',NULL,'Der Rückzug aus der Welt kann eine Verteidigungsoder Vermeidungsstrategie sein oder eine Möglichkeit, sich vor Verantwortung zu drücken. Wenn Sie sich von anderen und deren Meinungen abschotten, bauen Sie ein Gebäude der Illusion auf. Nicht engstirnig sein','draft-review','source-derived-draft'),
('major-09','CHILD','de','0.1.0','SICH ZEIT ZUM NACHDENKEN NEHMEN','["AUFGEKLÄRTHEIT", "EINSAMKEIT", "BESINNUNG", "MEDITATION", "SELBSTVERWIRKLICHUNG"]','Diese Karte erzählt von sich zeit zum nachdenken nehmen. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-10','ADULT','de','0.1.0','VERÄNDERUNGEN UND WENDEN','["WANDEL", "PLÖTZLICHER WECHSEL", "URSACHE UND WIRKUNG", "HÖHEN UND TIEFEN", "UNBERECHENBARKEIT"]','Das Rad des Schicksals erinnert uns daran, lass sich alles jederzeit ändern kann und dass wir ein gewisses Gleichgewicht bewahren müssen, egal, was uns das Leben bringt. Diese Karte befasst sich mit den Aspekten des Lebens, über die wir keine Kontrolle haben. Sie bezeichnet einen glücklichen Zufall oder ein zufälliges Treffen, das Positives bringt. Keiner aber kann vorhersagen, in welche Richtung sich das Rad des Schicksals dreht; es könnte sein, dass ein beliebiges Ereignis sorgfältig ausgearbeitete Pläne zunichte macht. Dies hat jedoch das Potenzial für neues Wachstum. Die neue Situation akzeptieren und daraus lernen. I 1 1',NULL,'Es kommt zu unerwarteten Rückschlägen; Dies ist kein guter Zeitpunkt für ein neues Unterfangen. Sie können die Ereignisse nicht kontrollieren und persönlichen Nutzen daraus ziehen. Verlassen Sie sich auf Ihre innere Kraft und akzeptieren Sie die Situation mit Gleichmut,','draft-review','source-derived-draft'),
('major-10','CHILD','de','0.1.0','VERÄNDERUNGEN UND WENDEN','["WANDEL", "PLÖTZLICHER WECHSEL", "URSACHE UND WIRKUNG", "HÖHEN UND TIEFEN", "UNBERECHENBARKEIT"]','Diese Karte erzählt von veränderungen und wenden. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-11','ADULT','de','0.1.0','EIN FAIRES ERGEBNIS ODER INTEGRITÄT','["BALANCE", "KONSEQUENZEN", "FAIRNESS", "SCHLICHTUNG", "ORDNUNG SCHAFFEN"]','Die Waagschale der Gerechtigkeit auf dieser Karte muss zwischen beiden Seiten ausgeglichen sein, wohingegen das zweiseitige Schwert andeutet, dass ein Ergebnis sowohl positiv als auch negativ ausfallen kann. Bei dieser Karte dreht sich alles um Fairness. Sie haben die richtige Entscheidung getroffen oder die Situation ist das Resultat Ihrer vergangenen Handlungen. Die Karte mag auf ein Rechtsurteil hinweisen, kann aber genauso gut auftauchen, wenn Sie darüber nachdenken, was zu tun ist; sie rät Ihnen, die Optionen sorgfältig abzuwägen und bei dem Entscheidungsprozess rationale Logik anzuwenden und auf Fairness zu achten. Im Tarot kann die Gerechtigkeit auch das Äquivalent von Karma sein - schlechte Taten in der Vergangenheit wiederholen sich oder eine freundliche Geste wird erwidert. Verantwortung übernehmen und vergangene Fehler eingestehen.',NULL,'Die Umstände sind ungerecht. Es hilft jedoch nicht sich darüber aufzuregen; manchmal läuft es einfach nicht so. wie Sie es gern hätten. Ruhiges, gleichmütiges Reagieren ist angesagt. Es vermeiden, über andere zu urteilen, da die vollständigen Fakten nicht bekannt sind.','draft-review','source-derived-draft'),
('major-11','CHILD','de','0.1.0','EIN FAIRES ERGEBNIS ODER INTEGRITÄT','["BALANCE", "KONSEQUENZEN", "FAIRNESS", "SCHLICHTUNG", "ORDNUNG SCHAFFEN"]','Diese Karte erzählt von ein faires ergebnis oder integrität. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-12','ADULT','de','0.1.0','EIN OPFER AUS FREIEN STÜCKEN','["INITIIERUNG", "UNTERWERFUNG", "DAS UNBEKANNTE", "TIEFE EINSICHT", "GROSSE LEBENSVERÄNDERUNG"]','Es ist selten möglich, ohne Anstrengungen alles zu haben, was man will. In den meisten Heldenmythen macht die Hauptfigur eine Zeit der Not und Opfer durch, die sie in dem Wissen erduldet, dass der Preis die ganze Mühsal wert ist. Wenn der Gehängte in einem Spread auftaucht, zeigt er, dass es einen Zweck und Grund für eine gegenwärtige Schwierigkeit gibt. Manchmal handelt es sich dabei um ein finanzielles Oper - der Fragesteller gibt beispielsweise eine Karriere in der Stadt auf, um den Traum, auf dem Land zu leben, zu verwirklichen oder sich ehrenamtlich im Ausland zu engagieren —, doch es kann auch sein, dass man eine Einstellung oder Glaubensrichtung aufgibt, um Raum für neue Ideen zu schaffen. Loslassen ist schmerzhaft und das Leben wird nicht mehr dasselbe sein, aber letztendlich gibt es größere Belohnungen.',NULL,'Ist das Opfer notwendig oder beruht es auf einem übertriebenen Pflichtgefühl? Der umgedrehte Gehängte deutet häufig auf ein leeres Märtyrertum hin. Überlegen, was Sie daran hindert Ihre eigenen Bedürfnisse und Wünsche zu verfolgen..','draft-review','source-derived-draft'),
('major-12','CHILD','de','0.1.0','EIN OPFER AUS FREIEN STÜCKEN','["INITIIERUNG", "UNTERWERFUNG", "DAS UNBEKANNTE", "TIEFE EINSICHT", "GROSSE LEBENSVERÄNDERUNG"]','Diese Karte erzählt von ein opfer aus freien stücken. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-13','ADULT','de','0.1.0','DAS ENDE EINER ÄRA','["VERÄNDERUNG", "UMWANDLUNG", "ENTFERNEN", "AKZEPTANZ", "VORAUSBLICKEN"]','Die Furcht vor dieser Karte ist unbegründet, denn sie dreht sich selten um den körperlichen Tod. Ihre Bedeutung ist metaphorisch und hat mit Beendung zu tun. Ein Ende kann ein Gefühl von Verlust und Trauer mit sich bringen, öffnet aber auch den Weg für einen Neubeginn. Daher kann man den Tod im Tarot als dynamische Kraft und die Gelegenheit für Veränderung sehen. Der Tod folgt dem Gehängten und deutet darauf hin, dass man das, was man verloren hat, freiwillig aufgegeben hat. Wie viel Schmerz das Ende hervorruft, hängt von Ihrer Fähigkeit ab, die Notwendigkeit dafür zu erkennen; gegen das Unvermeidliche anzukämpfen, ist unklug. Diese Karte ermutigt uns, das zu akzeptieren, was sich nicht ändern lässt, und die Vergangenheit aufzugeben, die wir sowieso nicht ändern können. Das Leben ist nicht statisch und alle Dinge haben ein Ende.',NULL,'Die Angst, loszulassen, und die Weigerung, weiterzumachen: bisweilen auch Angst vor dem körperlichen Tod. Wie bei der aufrechten Karte geht es häufiger um Veränderung und Ihre Einstellung dazu. GR0S3EAp, S3 39','draft-review','source-derived-draft'),
('major-13','CHILD','de','0.1.0','DAS ENDE EINER ÄRA','["VERÄNDERUNG", "UMWANDLUNG", "ENTFERNEN", "AKZEPTANZ", "VORAUSBLICKEN"]','Diese Karte erzählt von das ende einer ära. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-14','ADULT','de','0.1.0','EGENSATZLICHE ENERGIEN AUSGLEICHEN','["KOMPROMISS", "HARMONIE", "KOOPERATION", "TOLERANZ", "ANPASSUNG"]','Atempause und Ruhe vor diesen starken, lebensverändernden Mächten. Die Bildersymbolik der Karte — Flüssigkeit, die in einem endlosen Strahl zwischen zwei Gefäßen fließt - steht für den ungehinderten Fluss der Lebensenergie, die weder das eine Extrem noch das andere ist, sondern sich in einem steten Zustand von Strömung und Gleichgewicht befindet. Die Mäßigung rät zu Geduld, zur Suche nach einem Mittelweg und zur Zusammenarbeit mit anderen zugunsten aller. Sie kann Reife bedeuten, die Exzesse drosselt und extreme Emotionen mildert. In Kombination mit der Gerechtigkeit bedeutet sie ein willkommenes Urteil; mit den Liebenden weist sie auf gute Kommunikation und die Lösung von Konflikten hin. I 2 1',NULL,'Sie sind durch UnEntschlossenheit gelähmt oder befürchten, dass unterschiedliche Meinungen zu Zwietracht oder zur Trennung führen. Die Bereitschaft zur Zusammenarbeit in einer Partnerschaft oder einer Gruppe ist gering Nach Innen schauen und die Situation neu abschätzen.','draft-review','source-derived-draft'),
('major-14','CHILD','de','0.1.0','EGENSATZLICHE ENERGIEN AUSGLEICHEN','["KOMPROMISS", "HARMONIE", "KOOPERATION", "TOLERANZ", "ANPASSUNG"]','Diese Karte erzählt von egensatzliche energien ausgleichen. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-15','ADULT','de','0.1.0','UNGEZÜGELTE SELBSTGEFÄLLIGKEIT','["EHRGEIZ", "GENUSS", "EXZESS", "HEDONISMUS", "MACHTMISSBRAUCH"]','Die Teufel-Karte verkörpert Urtriebe, ungezügelte Lust und Gier. Diese wilde Energie kann aber auch eine kreative Kraft sein, wenn wir stark genug sind, sie zu zügeln. Das Tarot versteht, dass in uns allen ein Teufel steckt; wir können nicht eine äußere Kraft für unsere negativen Impulse verantwörtlich machen: Wir müssen sie vielmehr anerkennen und kontrollieren. Das Erscheinen des Teufels ist eine Warnung, sich nicht durch eine Überbetonung von körperlicher Freuden und Befriedigung in die Irre führen zu lassen oder eigene Wünsche auf eine Art zu verfolgen, die für Sie oder andere schädlich ist. Der Teufel kann auf eine unangenehme Situation hinweisen, in der es um Machtspiele, Exzess, Schuld oder Sucht geht. Wenn Sie die falsche Wahl getroffen haben oder über die Motive eines anderen im Dunkeln tappen, dies bereinigen.',NULL,'Sie erkennen allmählich, dass negative Gewohnheiten oder egoistische Entscheidungen zum Unglücklichsein geführt haben. // DERTURM DER STERN 31 XVII CHAOS UNTERBRECHUNG VERÄNDERUNG ZERSTÖRUNG BEFREIUNG Der Turm ist das einzige Gebäude im Tarot und bezeichnet die Bauwerke, die wir zu Sicherheit und unserem Schutz er-','draft-review','source-derived-draft'),
('major-15','CHILD','de','0.1.0','UNGEZÜGELTE SELBSTGEFÄLLIGKEIT','["EHRGEIZ", "GENUSS", "EXZESS", "HEDONISMUS", "MACHTMISSBRAUCH"]','Diese Karte erzählt von ungezügelte selbstgefälligkeit. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-16','ADULT','de','0.1.0','DRAMATISCHER UMBRUCH,','["EINE WIEDERGEBURT ANKUNDIGT", "unserer"]','Form annehmen wie unser Zuhause oder abstrakt sein wie die berufliche und gesellschaftliche Persona, die wir im öffentlichen Leben präsentieren; häufig sind sie aber auch emotionaler Art wie in Beziehungen, die Zuflucht vor der Außenwelt bieten. Die Karte stellt einen vom Blitz getroffenen Turm dar, was eine Katastrophe anzeigt, bei der alles zu Boden stürzt - vielleicht das Ende einer Partnerschaft, eine Entlassung oder der Verlust, an sich selbst zu glauben. Der Turm ist zwar eine destruktive Karte, birgt aber auch Chancen: Ist das Alte nämlich vernichtet, so ist Platz für das Neue, wenn Sie gewillt sind, noch einmal von vorn zu beginnen. Eine bessere Lebensweise ist möglich.',NULL,'・・ BEDEUTUNG DER UMGEKEHRTEN KARTE: Die unangenehmen Ereignisse, die eintreten, sind eine Folge Ihrer eigenen Handlungen, oder Sie leugnen dies und versuchen, das Unvermeidliche hinauszuzogern.Zeit, der Realität ins Auge zu blicken.','draft-review','source-derived-draft'),
('major-16','CHILD','de','0.1.0','DRAMATISCHER UMBRUCH,','["EINE WIEDERGEBURT ANKUNDIGT", "unserer"]','Diese Karte erzählt von dramatischer umbruch,. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-17','ADULT','de','0.1.0','EIN_VERSPRECHEN','["JR GLUCKLICHERE ZEITEN", "INSPIRATION", "IDEALISMUS", "FÜHRUNG", "EINSICHT"]','Der Stern ist eine spirituelle Karte, die uns in eine bessere Zukunft lockt. Er symbolisiert Glauben an uns selbst, an eine höhere Macht oder an den Wert einer neuen Idee oder Ambition. Der Stern verkörpert unseren unschuldigen Teil, der Hoffnung hegt, selbst wenn scheinbar alles verloren ist. Diese Karte, die häufig in schwierigen Zeiten erscheint, zeigt, dass das Schlimmste vorüber ist, und ermutigt Sie, daran zu glauben, dass das Leben besser wird. Sie rät, offen für die Hilfe zu sein, die Ihnen nun angeboten wird, sei es von Menschen aus Ihrem Umkreis oder vom Universum. Der Stern kann darauf hinweisen, dass Sie im Begriff sind, einen Weg einzuschlagen, der spirituelle oder kreative Erfüllung bringt. Wichtig ist, daran zu denken, dass der Stern nicht die sachliche Seite des Lebens berücksichtigt; ihre Aufgabe ist die, diesen Idealismus mit praktischen Aspekten zu verbinden. 31',NULL,'Der umgekehrte Stern kann Eigennutz oder einen Verlust des Idealismus bedeuten: vielleicht hat eine Idee oder eine Beziehung an Glanz verloren oder Sie können Probleme erkennen, die Sie bislang nicht wahrhaben wollten. --• GROSSE 4t, 43','draft-review','source-derived-draft'),
('major-17','CHILD','de','0.1.0','EIN_VERSPRECHEN','["JR GLUCKLICHERE ZEITEN", "INSPIRATION", "IDEALISMUS", "FÜHRUNG", "EINSICHT"]','Diese Karte erzählt von ein_versprechen. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-18','ADULT','de','0.1.0','FANTASIE UND SCHWANKENDE EMOTIONEN','["INTUITION", "KREATIVITÄT", "MISSVERSTÄNDNISSE", "UNBEHAGEN", "UNGEWISSHEIT"]','Im Tarot ist der Mond mit dem Unterbewusstsein verbunden; dies stützt sich auf die seit langem verbreitete Überzeugung, dass menschliches Verhalten durch das Zuund Abnehmen des Mondes in seinem kontinuierlichen Zyklus beeinflusst wird. Wenn der Mond in einem Spread auftaucht, bedeutet dies oft eine Zeit der Verwirrung, da wir die Tiefen des Unterbewusstseins nicht ergründen können oder die Richtung, in die es uns steuert, nicht verstehen. Der Mond erscheint auch, wenn Ihre Träume besonders lebhaft sind oder wenn Sie sich zu künstlerischen Hobbys, Meditation, Wahrsagen und vielleicht auch Psychotherapie hingezogen fühlen, die alle zu größerem Verständnis führen können. Wenn Sie sich unsicher fühlen, dies akzeptieren, die innere Psyche so gut es geht erforschen und Entscheidungen bis zur nächsten Phase des Zyklus verschieben. I €',NULL,'Eine scheinbar klare Situation erweist sich als Illusion, oder verborgene Motive sind mit im Spiel. Mangelnde Klarheit führt häufig zu Schwierigkeiten: daher gut nachdenken, bevor Sie etwas sagen, und sich nicht in sinnlose Diskussionen hineinziehen lassen. Hören Sie auf Ihre innere Stimme.','draft-review','source-derived-draft'),
('major-18','CHILD','de','0.1.0','FANTASIE UND SCHWANKENDE EMOTIONEN','["INTUITION", "KREATIVITÄT", "MISSVERSTÄNDNISSE", "UNBEHAGEN", "UNGEWISSHEIT"]','Diese Karte erzählt von fantasie und schwankende emotionen. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-19','ADULT','de','0.1.0','STRAHLENDE ENERGIE','["DURCHBRUCH", "KRÄFTIGUNG", "GESUNDHEIT", "FREIHEIT", "ERRUNGENSCHAFT"]','Die Sonne wird in Mythen und Erzählungen aus aller Welt und aus jeder Ära gefeiert, eine Anerkennung ihrer entscheidenden Rolle für die Erhaltung des Lebens. Wenn die Sonne in einem Spread auftaucht, wissen Sie, dass Sie die nötige Vitalität und Begeisterung haben, alles zu meistern, was vor Ihnen liegt. Die Chancen für Abenteuer und Fröhlichkeit stehen gut für Sie. Die Sonne deutet darauf hin, dass Sie an der Reihe sind, zu strahlen, und Ereignisse sind zu Ihren Gunsten. Vielleicht gibt es eine Beförderung oder Fortuna wartet auf Sie. Andere fühlen sich von Ihrer Ausstrahlung und Energie angezogen. Dies ist eine wunderbare Zeit für Geselligkeit und Spaß. Verpassen Sie diese Gelegenheit nicht. Wenn wir uns im Zentrum des Universums befinden, werden unsere Wünsche erreichbar und wir müssen den Tag nutzen.',NULL,'Wenn die Sonne zu hell scheint, können andere geblendet werden. Achten Sie darauf, nicht arrogant oder überlegen zu sein. Es kann auch sein, dass Ihr Licht verblasst: So wie das Sonnenlicht erlöscht, wenn die Sonne am Horizont versinkt, können Gelegenheiten entgehen. 31 31 31 31 31 2 31 31 单 31','draft-review','source-derived-draft'),
('major-19','CHILD','de','0.1.0','STRAHLENDE ENERGIE','["DURCHBRUCH", "KRÄFTIGUNG", "GESUNDHEIT", "FREIHEIT", "ERRUNGENSCHAFT"]','Diese Karte erzählt von strahlende energie. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-20','ADULT','de','0.1.0','LETZTE WAHLEN TREFFEN','["RECHENSCHAFT", "ENTSCHEIDUNGEN", "VERGEBUNG", "VERANTWORTLICHKEIT", "SELBSTVERTRAUEN"]','Es ist sinnvoll, sich die umliegenden Karten anzuschauen und festzustellen, in welchem Bereich Urteilsvermögen erforderlich ist. Ist das Gericht mit den Liebenden gepaart, so wird eine Beziehung eventuell durch Heirat formalisiert; in Verbindung mit dem Hierophanten legt die Karte eine Verpflichtung Ihrem Glauben gegenüber nahe. Sie sind bereit, Ihre Fähigkeiten kritisch abzuschätzen und notwendige Verbesserungen vorzunehmen. Ihr Urteil ist klar, und Sie gleichen intuitives Selbst und logisches Denken perfekt ab.',NULL,'Die Angst vor Entscheidungen oder vielleicht auch ein übermäßiges Vertrauen auf die Meinung anderer kann zu einer verpassten Gelegenheit führen. Die KLEINE ARKANA Die 56 Karten der Kleinen Arkana geben einen tiefen Einblick in die Art und Weise, wie das Tarot Ihnen tagtäglich helfen kann, Sie zu leiten, mental aufzubauen und zu motivieren. Die Tarotkarten konzentrieren sich nämlich auf den praktischeren und nüchterneren Teil unseres Lebens wie Zielsetzung, Strategieentwicklung und Miteinbeziehen von Intuition. Achten Sie bei der Reise durch die zweite Hälfte der Tarotkarten auf die Schlüsselthemen der Farbkarten sowie darauf, welche Karten Ihnen ganz besonders auffallen. SENE 16 49','draft-review','source-derived-draft'),
('major-20','CHILD','de','0.1.0','LETZTE WAHLEN TREFFEN','["RECHENSCHAFT", "ENTSCHEIDUNGEN", "VERGEBUNG", "VERANTWORTLICHKEIT", "SELBSTVERTRAUEN"]','Diese Karte erzählt von letzte wahlen treffen. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('major-21','ADULT','de','0.1.0','Ankommen, ohne stehen bleiben zu müssen','["Ganzheit", "Abschluss", "Verbundenheit"]','Die Welt steht für Abschluss, Ganzheit und die Würdigung einer zurückgelegten Entwicklung. Ein Ende kann vollständig sein, auch wenn danach etwas Neues beginnt.',NULL,'Die andere Blickrichtung fragt, ob Perfektionsansprüche einen Abschluss verhindern oder ob ein letzter Schritt noch bewusst vollzogen werden möchte.','draft-review','neuroways-fallback'),
('major-21','CHILD','de','0.1.0','Ankommen, ohne stehen bleiben zu müssen','["Ganzheit", "Abschluss", "Verbundenheit"]','Diese Karte erzählt von ankommen, ohne stehen bleiben zu müssen. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('wands-ace','ADULT','de','0.1.0','ANREIZ · DURCHBRUCH · ZÜNDUNG','["ANREIZ", "DURCHBRUCH", "ZÜNDUNG"]','Die Ideen-Karte. Wenn das Ass der Stäbe erscheint, kündigt es einen Aufschwung kreativer Energie an, die Ihr Schicksal verändern kann. Achten Sie auf neue Erkenntnisse, plötzliche Inspiration oder einfach auf ein Gefühl der Unruhe — dies deutet darauf hin, dass Sie am Rande eines neuen Abenteuers stehen. Ein Erbe oder ein unerwarteter Bonus können die Dinge vorantreiben.',NULL,'Mangelnde Motivation oder das Gefühl, eingeengt zu sein, führen dazu, dass kreative Ideen erstickt werden. Oder haben Sie einfach zu viel zu tun? Es ist ein guter Schachzug, eine Pause einzulegen. 4 纟 ，響 31 7m赫就 31','draft-review','source-derived-draft'),
('wands-ace','CHILD','de','0.1.0','ANREIZ · DURCHBRUCH · ZÜNDUNG','["ANREIZ", "DURCHBRUCH", "ZÜNDUNG"]','Diese Karte erzählt von anreiz · durchbruch · zündung. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('wands-02','ADULT','de','0.1.0','MÜHE · PLANUNG · VORBEREITUNG','["MÜHE", "PLANUNG", "VORBEREITUNG"]','Es erfordert nachhaltige Anstrengungen, eine neue Idee in die Tat umzusetzen. Glauben Sie an Ihr Potenzial und unternehmen Sie mutige Schritte, es zu realisieren. Die Welt liegt Ihnen zu Füßen. Diese Karte zeigt eine Entscheidung an: entweder mit Bekanntem fortfahren oder eine völlig neue Richtung einschlagen. Eine neue, fruchtbare Partnerschaft zeichnet sich ab.',NULL,'Vorsichtig sein. Pläne sind nicht durchdacht worden und es kann zu Missverständnissen kommen. Eine Idee endet in einer Enttäuschung.','draft-review','source-derived-draft'),
('wands-02','CHILD','de','0.1.0','MÜHE · PLANUNG · VORBEREITUNG','["MÜHE", "PLANUNG", "VORBEREITUNG"]','Diese Karte erzählt von mühe · planung · vorbereitung. Du kannst schauen, ob dich daran heute etwas erinnert. Die Karte sagt nicht voraus, was passieren wird. Sie kann dir nur helfen, eine Situation aus einer neuen Richtung anzusehen.',NULL,'Manchmal fühlt sich dieselbe Idee ganz anders an. Vielleicht ist etwas zu viel, zu wenig oder gerade nicht passend. Dann darfst du langsamer machen, nachfragen oder dir Hilfe holen.','draft-review','child-neuroways-derived'),
('wands-03','ADULT','de','0.1.0','Entwicklung und Verbindung · Energie, Initiative und schöpferische Bewegung','["Entwicklung", "Energie"]','Drei der Stäbe verbindet den Grundton der Stäbe – energie, initiative und schöpferische bewegung – mit dem Entwicklungsmotiv „entwicklung und verbindung“. Die Karte kann als Einladung gelesen werden, die aktuelle Situation aus dieser Perspektive zu betrachten, ohne daraus eine feste Vorhersage abzuleiten.',NULL,'Die andere Blickrichtung fragt, ob dieses Thema gerade zu stark, zu schwach oder unter unpassenden Bedingungen gelebt wird und welche zusätzliche Information, Grenze oder Unterstützung hilfreich wäre.','draft-review','neuroways-structured-fallback'),
